import { SQLWrapper, and, eq, like, ilike, lt, lte, gt, gte } from "drizzle-orm"
import { AnyMySqlTable } from "drizzle-orm/mysql-core"

type SortCondition = {
    column: any
    direction: 'asc' | 'desc'
    nulls: 'first' | 'last' | null
}

/**
 * Parses URLSearchParams to generate Drizzle ORM where conditions, limit and sorting.
 * This function was designed to work with the URL parameters
 * generated by the loadSubsetOptions in @tanstack/react-db.
 * Supports suffixes: _eq, _lt, _lte, _gt, _gte, _like, _ilike
 * 
 * @param params URLSearchParams from the request
 * @param table Drizzle ORM table schema
 * @returns SQLWrapper representing the where conditions
 */
export function urlParamsParser(params: URLSearchParams, table: AnyMySqlTable) {
    const limit = parseInt(params.get('limit') || '0', 10)
    const whereConditions: SQLWrapper[] = []
    const sortCondition: SortCondition[] = []

    params.forEach((value, key) => {
        if (key === 'limit') return
        if (key === 'sort') {
            const [field, direction, nulls] = value.split(':')
            const col = (table as any)[field]
            if (!col) return
            sortCondition.push({
                column: col,
                direction: direction === 'desc' ? 'desc' : 'asc',
                nulls: nulls === 'first' ? 'first' : nulls === 'last' ? 'last' : null
            })
        } else if (key.endsWith('_eq')) {
            const field = key.slice(0, -3)
            const col = (table as any)[field]
            if (!col) return
            whereConditions.push(eq(col, value))
        } else if (key.endsWith('_lt')) {
            const field = key.slice(0, -3)
            const col = (table as any)[field]
            if (!col) return
            whereConditions.push(lt(col, value))
        } else if (key.endsWith('_lte')) {
            const field = key.slice(0, -4)
            const col = (table as any)[field]
            if (!col) return
            whereConditions.push(lte(col, value))
        } else if (key.endsWith('_gt')) {
            const field = key.slice(0, -3)
            const col = (table as any)[field]
            if (!col) return
            whereConditions.push(gt(col, value))
        } else if (key.endsWith('_gte')) {
            const field = key.slice(0, -4)
            const col = (table as any)[field]
            if (!col) return
            whereConditions.push(gte(col, value))
        } else if (key.endsWith('_like')) {
            const field = key.slice(0, -5)
            const col = (table as any)[field]
            if (!col) return
            whereConditions.push(like(col, `%${value}%`))
        } else if (key.endsWith('_ilike')) {
            const field = key.slice(0, -6)
            const col = (table as any)[field]
            if (!col) return
            whereConditions.push(ilike(col, `%${value}%`))
        }
    })

    return {
        limit: limit === 0 ? undefined : limit,
        sort: sortCondition,
        whereConditions: and(...whereConditions)
    }
}